modules.kernel/v1/errors.skir:
// Empty typed failure used when an operation cannot expose a recoverable domain cause.
// It is the protocol marker for internal failure, not a message or diagnostic payload.
struct InternalError {}

// Reports a record table mismatch at a typed boundary.
// expected_table names the required table. given_tables names the distinct tables found in the input.
struct InvalidRecordIdError {
  expected_table: string;
  given_tables: [string];
}

modules.kernel/v1/bounded_transfer.skir:
// One part of an encoded response, distinct from a resumable artifact blob upload.
// All chunks share transfer identity, total encoded byte size, chunk count, and SHA256 digest.
// Indices start at zero. Receivers may assemble out of order but must verify the complete size
// and digest before decoding; a repeated index is valid only when its bytes match.
struct BoundedTransferChunk {
  transfer_id: string = 0;
  index: int32 = 1;
  chunk_count: int32 = 2;
  encoded_size: int64 = 3;
  sha256: string = 4;
  payload: bytes = 5;
}

modules.kernel/v1/color.skir:
// Shared color value. The canonical representation is one ARGB 32 bit value.
// Consumers convert the signed wire integer to an unsigned 32 bit color without changing its bits.
struct Color {
  argb: int32 = 0;
}

modules.kernel/v1/duration.skir:
// Shared elapsed time value. The canonical unit is milliseconds.
// Consumers translate this value to native duration types only at their boundaries.
struct Duration {
  milliseconds: int64;
}

modules.kernel/v1/record_id.skir:
// Canonical entity identity is the pair of a table name and a typed key.
// The table selects the identity namespace. The key remains typed through transport and database adapters.
// A string key is the opaque application identity used by resource routes. Query formatting is a separate concern.
struct RecordId {
  table: string;
  key: RecordIdKey;
}

// Record identity keys support scalar and compound forms.
// Arrays and objects are key structures, not interchangeable string encodings.
enum RecordIdKey {
  number: int64;
  string: string;
  uuid: string;
  array: [RecordIdValue];
  object: [ObjectRecordIdKey|key];
}

// One named member of an object key. The keyed list preserves the member name beside its typed value.
struct ObjectRecordIdKey {
  key: string;
  value: RecordIdValue;
}

// Values nested inside compound record keys. This is broader than RecordIdKey because nested values can be null or boolean.
enum RecordIdValue {
  null;
  boolean: bool;
  number: int64;
  float: float64;
  string: string;
  array: [RecordIdValue];
  object: [ObjectRecordIdValue|key];
}

// One named member of an object value. Its value may recursively contain arrays and objects.
struct ObjectRecordIdValue {
  key: string;
  value: RecordIdValue;
}

